// BK_ENVLOAD_APPLIED: some hosts (e.g. Botkeep) deliver environment variables through a .env file
// inside the container instead of the process environment. Load it before anything reads
// process.env; variables already present in the process environment always win.
try {
  const fs0 = require('fs');
  const path0 = require('path');
  for (const p0 of [path0.join(process.cwd(), '.env'), path0.join(__dirname, '.env')]) {
    if (fs0.existsSync(p0)) {
      for (const line0 of fs0.readFileSync(p0, 'utf8').split(/\r?\n/)) {
        const m0 = line0.match(/^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*?)\s*$/);
        if (m0 && process.env[m0[1]] === undefined) {
          let v0 = m0[2];
          if ((v0.startsWith('"') && v0.endsWith('"')) || (v0.startsWith("'") && v0.endsWith("'"))) v0 = v0.slice(1, -1);
          process.env[m0[1]] = v0;
        }
      }
      break;
    }
  }
} catch (e0) { /* .env is optional */ }

