const ANSI = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  dim: '\x1b[2m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
  electric: '\x1b[38;5;39m',
  navy: '\x1b[38;5;25m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  red: '\x1b[31m',
  magenta: '\x1b[35m',
  white: '\x1b[37m'
};

class Logger {
  static quiet = false;

  static banner() {
    if (this.quiet) return;
    const shield = `
${ANSI.electric}${ANSI.bold}     ____     _       __     __   _        _  __   ___         ____     _        _____    _____
    / ___|   / \\      \\ \\   / /  / \\      | |/ /  |_ _|       / ___|   / \\      |_   _|  | ____|
    \\___ \\  / _ \\      \\ \\ / /  / _ \\     | ' /    | |       | |  _   / _ \\       | |    |  _|
     ___) | / ___ \\     \\ V /   / ___ \\   | . \\    | |       | |_| |  / ___ \\     | |    | |___
    |____/  /_/   \\_\\    \\_/    /_/   \\_\\ |_|\\_\\  |___|       \\____|  /_/   \\_\\   |_|    |_____|
  ${ANSI.white}One port. Many paths.${ANSI.electric}
  ${ANSI.dim}Stream Without Limits${ANSI.electric}
${ANSI.reset}`;
    console.log(shield);
    console.log(`${ANSI.cyan}================================================================${ANSI.reset}`);
    console.log(`${ANSI.bold}${ANSI.electric}  SAVAKI GATE ${ANSI.white}• Running on ${bkPlatformName()}${ANSI.reset}`);
    console.log(`${ANSI.dim}  Channel: Savaki (https://t.me/saeedsavaki)${ANSI.reset}`);
    console.log(`${ANSI.cyan}================================================================${ANSI.reset}\n`);
  }

  static renewNotice() {}

  static info(msg) {
    if (!this.quiet) console.log(`${ANSI.cyan}[i] ${msg}${ANSI.reset}`);
  }

  static success(msg) {
    if (!this.quiet) console.log(`${ANSI.green}[OK] ${msg}${ANSI.reset}`);
  }

  static warn(msg) {
    if (!this.quiet) console.log(`${ANSI.yellow}[!] ${msg}${ANSI.reset}`);
  }

  static error(msg) {
    console.error(`${ANSI.red}[X] ${msg}${ANSI.reset}`);
  }

  static step(msg) {
    if (!this.quiet) console.log(`${ANSI.electric}==> ${msg}${ANSI.reset}`);
  }

  static item(label, val) {
    if (!this.quiet) {
      console.log(`  ${ANSI.cyan}${label.padEnd(18)}:${ANSI.reset} ${ANSI.white}${val}${ANSI.reset}`);
    }
  }

  static section(title) {
    if (!this.quiet) {
      console.log(`\n${ANSI.bold}${ANSI.electric}--- ${title} ---${ANSI.reset}`);
    }
  }
}

